    "field.auth_title": "Accesso dal campo",
    "field.auth_subtitle": "Inserisci il PIN a 6 cifre ricevuto via SMS per iniziare.",
    "field.auth_pin": "PIN",
    "field.auth_pin_invalid": "Inserisci il PIN a 6 cifre ricevuto via SMS.",
