    "cases.answer_the_estudio_with_a_plan_de_seguridad.step.checks.out.evidence": "Evidenza datata di ogni controllo",
    "cases.answer_the_estudio_with_a_plan_de_seguridad.step.record.in.site": "Lavori di cantiere in corso",
    "cases.answer_the_estudio_with_a_plan_de_seguridad.step.record.in.forms": "Moduli di controllo completati",
